insert into public.feature_flags(tenant_id,flag_key,flag_name,description,is_enabled,allowed_tiers,config_json) values(null,'medical_files','Medical Files','Core Medical Files capability; viewing is available to authorized users across tiers.',true,array['trial','basic','pro','enterprise'],jsonb_build_object('default_workspace','administrative','contextual_widget',true,'advanced_capabilities',true)) on conflict(tenant_id,flag_key) do update set is_enabled=excluded.is_enabled,allowed_tiers=excluded.allowed_tiers,config_json=excluded.config_json,updated_at=now();
